<?php

namespace Softminal\ImageCraft;

use Softminal\ImageCraft\Services\NextGenConverter;
use Softminal\ImageCraft\Services\Settings;

if (!defined('ABSPATH')) {
    exit;
}

/**
 * Next-gen format delivery (WebP / AVIF) — public-frontend surface.
 *
 * Serves the sidecar files that NextGenConverter generated by wrapping content
 * <img> tags in <picture> with <source type="image/avif|webp"> entries and the
 * ORIGINAL <img> kept as the universal fallback. Nothing is rewritten in the
 * database; browsers without next-gen support (or images without sidecars)
 * load exactly what they always loaded.
 *
 * Safety model (mirrors Fallback.php — this is the plugin's second public
 * surface): opt-in and default OFF; frontend hooks only register when the
 * toggle is on; every callback does cheap bails first and is wrapped so it can
 * never fatal a visitor-facing page. The delete_attachment cleanup hook is
 * registered unconditionally (deletions happen in wp-admin) so sidecars can
 * never orphan on disk, even while delivery is switched off.
 */
class NextGen
{
    /** @var NextGenConverter */
    private $converter;

    /** @var array<int, array|false> Per-request manifest cache. */
    private static $manifests = [];

    /** @var array{basedir:string, baseurl:string}|null */
    private static $uploads = null;

    public function __construct()
    {
        $this->converter = new NextGenConverter();
    }

    public function init(): void
    {
        // Cleanup must work everywhere (delete_attachment fires in admin).
        add_action('delete_attachment', [$this, 'onDeleteAttachment']);

        if (is_admin()) {
            return;
        }

        if (Settings::get('icais_nextgen_delivery_enabled', '0') !== '1') {
            return;
        }

        // WP 6.0+ per-<img> content filter — far safer than regexing the whole
        // post body. On older WP the content path is simply skipped (floor is
        // 5.8); thumbnails below still work everywhere.
        add_filter('wp_content_img_tag', [$this, 'filterContentImg'], 20, 3);
        add_filter('post_thumbnail_html', [$this, 'filterThumbnailHtml'], 20, 3);
    }

    /**
     * delete_attachment: remove the attachment's sidecar files + manifest.
     * Defensive — a cleanup failure must never break the deletion flow.
     */
    public function onDeleteAttachment($postId): void
    {
        try {
            $this->converter->clean((int) $postId);
        } catch (\Throwable $e) {
            if (defined('WP_DEBUG') && WP_DEBUG) {
                error_log('ImageCraft nextgen cleanup on delete #' . (int) $postId . ': ' . $e->getMessage());
            }
        }
    }

    /**
     * wp_content_img_tag: wrap a content <img> in <picture> when sidecars exist.
     *
     * @param string $img          The full <img ...> tag HTML.
     * @param string $context      Calling context (unused).
     * @param int    $attachmentId Attachment ID (0 when WP couldn't detect one).
     * @return string
     */
    public function filterContentImg($img, $context, $attachmentId): string
    {
        try {
            $img = (string) $img;
            $attachmentId = (int) $attachmentId;
            if ($attachmentId <= 0 || $img === '' || stripos($img, '<img') === false) {
                return $img;
            }
            return $this->wrapInPicture($img, $attachmentId);
        } catch (\Throwable $e) {
            return (string) $img;
        }
    }

    /**
     * post_thumbnail_html: same treatment for featured images.
     */
    public function filterThumbnailHtml($html, $postId, $thumbnailId): string
    {
        try {
            $html = (string) $html;
            $thumbnailId = (int) $thumbnailId;
            if ($thumbnailId <= 0 || $html === '' || stripos($html, '<img') === false) {
                return $html;
            }
            // Bail if some other layer already produced a <picture>.
            if (stripos($html, '<picture') !== false) {
                return $html;
            }
            return $this->wrapInPicture($html, $thumbnailId);
        } catch (\Throwable $e) {
            return (string) $html;
        }
    }

    // ---------------------------------------------------------------------
    // Internals
    // ---------------------------------------------------------------------

    /**
     * Wrap an <img> tag in <picture> with an AVIF and/or WebP <source> whose
     * srcset mirrors the img's own srcset, entry-by-entry, keeping only the
     * entries whose sidecar file actually exists. If no entry qualifies, the
     * tag is returned untouched.
     */
    private function wrapInPicture(string $img, int $attachmentId): string
    {
        $sidecars = $this->sidecarSet($attachmentId);
        if ($sidecars === []) {
            return $img;
        }

        // The img's candidate URLs: srcset if present, else src.
        $srcset = $this->extractAttribute($img, 'srcset');
        $src = $this->extractAttribute($img, 'src');
        $candidates = $srcset !== '' ? $srcset : $src;
        if ($candidates === '') {
            return $img;
        }

        $sizes = $this->extractAttribute($img, 'sizes');

        $sources = '';
        foreach (['avif', 'webp'] as $format) {
            $converted = $this->convertSrcset($candidates, $format, $sidecars);
            if ($converted === '') {
                continue;
            }
            $sources .= '<source type="image/' . $format . '" srcset="' . esc_attr($converted) . '"'
                . ($sizes !== '' ? ' sizes="' . esc_attr($sizes) . '"' : '')
                . '>';
        }

        if ($sources === '') {
            return $img;
        }

        return '<picture>' . $sources . $img . '</picture>';
    }

    /**
     * Rewrite each srcset entry's URL to its next-gen sidecar, dropping
     * entries that have none. "a.jpg 300w, b.jpg 1024w" → "a.jpg.webp 300w".
     */
    private function convertSrcset(string $srcset, string $format, array $sidecars): string
    {
        $out = [];
        foreach (explode(',', $srcset) as $entry) {
            $entry = trim($entry);
            if ($entry === '') {
                continue;
            }
            $parts = preg_split('/\s+/', $entry, 2);
            $url = $parts[0];
            $descriptor = isset($parts[1]) ? ' ' . $parts[1] : '';

            $relative = $this->uploadsRelative($url);
            if ($relative === '' || !isset($sidecars[$relative . '.' . $format])) {
                continue;
            }
            $out[] = $url . '.' . $format . $descriptor;
        }

        return implode(', ', $out);
    }

    /**
     * The attachment's sidecar files as a lookup set of uploads-relative
     * paths (normalized to forward slashes). Cached per request.
     *
     * @return array<string, true>
     */
    private function sidecarSet(int $attachmentId): array
    {
        if (!isset(self::$manifests[$attachmentId])) {
            $manifest = get_post_meta($attachmentId, NextGenConverter::META_MANIFEST, true);
            $set = [];
            if (is_array($manifest) && !empty($manifest['files']) && is_array($manifest['files'])) {
                foreach ($manifest['files'] as $file) {
                    if (is_string($file) && $file !== '') {
                        $set[str_replace('\\', '/', $file)] = true;
                    }
                }
            }
            self::$manifests[$attachmentId] = $set;
        }

        return self::$manifests[$attachmentId] ?: [];
    }

    /** Map an uploads URL to its uploads-relative file path ('' if outside). */
    private function uploadsRelative(string $url): string
    {
        if (self::$uploads === null) {
            $uploads = wp_get_upload_dir();
            self::$uploads = [
                'basedir' => (string) ($uploads['basedir'] ?? ''),
                'baseurl' => (string) ($uploads['baseurl'] ?? ''),
            ];
        }

        $baseurl = self::$uploads['baseurl'];
        if ($baseurl === '') {
            return '';
        }

        // Scheme-insensitive prefix match (https page serving http-registered uploads).
        $normalizedUrl = preg_replace('#^https?:#i', '', $url);
        $normalizedBase = preg_replace('#^https?:#i', '', $baseurl);
        if (strpos($normalizedUrl, $normalizedBase) !== 0) {
            return '';
        }

        $relative = ltrim(substr($normalizedUrl, strlen($normalizedBase)), '/');
        // Strip any query string (cache busters).
        $relative = strtok($relative, '?');

        return $relative === false ? '' : $relative;
    }

    /** Extract an attribute value from a single HTML tag string. */
    private function extractAttribute(string $tag, string $attribute): string
    {
        if (preg_match('/\b' . preg_quote($attribute, '/') . '\s*=\s*(["\'])(.*?)\1/is', $tag, $m)) {
            return trim($m[2]);
        }
        return '';
    }
}
